+            throw new IllegalArgumentException("가용 범위는 양끝이 함께 있거나 함께 없어야 합니다.");
+        }
+    }
+
+    public static AvailableRange empty() {
+        return EMPTY;
+    }
+
+    public boolean isEmpty() {
+        return firstCaseEndMonth == null;
+    }
+}

